#!/usr/bin/env bash
# Renames every image in static/img to PascalCase-Theme.ext, updates every reference to them,
# and adds srcDark to every <Figure> whose image has a dark version.
# Works on the existing dcu-update-check branch. Nothing is committed.
# Run from the project root in Git Bash:  bash rename-all-images.sh
set -euo pipefail
cd "$(dirname "$0")"
command -v node >/dev/null || { echo "ERROR: node not found (it comes with your Docusaurus setup)"; exit 1; }
git rev-parse --is-inside-work-tree >/dev/null 2>&1 || { echo "ERROR: not a git repository"; exit 1; }

BRANCH="dcu-update-check"
if [[ "$(git rev-parse --abbrev-ref HEAD)" != "$BRANCH" ]]; then
  git checkout "$BRANCH" || { echo "ERROR: could not switch to $BRANCH. Commit or stash your changes and run again."; exit 1; }
fi
echo "On branch $BRANCH"

node - <<'JS'
const fs = require('fs'), path = require('path'), { execFileSync } = require('child_process');
