-Dark.jpg"],["docs/intro.mdx","/img/0-Intro/DCUInitializationScreen-Light.jpg","/img/0-Intro/DCUInitializationScreen-Dark.png"],["docs/intro.mdx","/img/0-Intro/DCUDashboard-Light.jpg","/img/0-Intro/DCUDashboard-Dark.png"]]};
const git = (...a) => execFileSync('git', a, { encoding: 'utf8', maxBuffer: 64 << 20 });
const die = m => { console.error('ERROR: ' + m); process.exit(1); };

// ---- 1. Safety checks against what git tracks (matched ignoring case, as Windows does)
const tracked = git('ls-files', '-z', '--', 'static').split('\0').filter(Boolean);
const byLower = new Map(tracked.map(p => [p.toLowerCase(), p]));
const todo = [];
for (const [oldP, newP] of DATA.renames) {
  const src = byLower.get(oldP.toLowerCase());
  if (!src) die(`not tracked by git: ${oldP} (already renamed? the script only runs once)`);
  const clash = byLower.get(newP.toLowerCase());
  if (clash && clash.toLowerCase() !== src.toLowerCase()) die(`target already exists: ${newP}`);
  todo.push([src, newP]);
}
for (const f of Object.keys(DATA.edits)) if (!fs.existsSync(f)) die(`missing file: ${f}`);
console.log(`Checks passed: ${todo.length} images to rename, ${Object.keys(DATA.edits).length} files to update.`);

// ---- 2. Rename images with git mv (keeps history). Case-only renames go through a temporary name.
let n = 0;
for (const [src, dst] of todo) {
  fs.mkdirSync(path.dirname(dst), { recursive: true });
  if (src.toLowerCase() === dst.toLowerCase()) {
    git('mv', src, dst + '.tmp-rename');
    git('mv', dst + '.tmp-rename', dst);
  } else {
    git('mv', src, dst);
  }
  if (++n % 50 === 0) console.log(`  renamed ${n}/${todo.length}`);
}
console.log(`Renamed ${n} images.`);

// ---- 3a. Remove folders the renames left empty (e.g. 3-VoltageTest after moving to 3-VoltageTests)
for (const d of [...new Set(todo.map(([s]) => path.posix.dirname(s)))].sort((a, b) => b.length - a.length)) {
  let cur = d;
  while (cur.startsWith('static/img/') && fs.existsSync(cur) && fs.readdirSync(cur).length === 0) {
    fs.rmdirSync(cur); console.log(`Removed empty folder ${cur}`); cur = path.posix.dirname(cur);
  }
}

// ---- 3b. Make folder names on disk match git (Windows keeps the old case of an existing folder)
const dirs = [...new Set(todo.map(([, d]) => path.posix.dirname(d)))];
const removeIfEmpty = p => { try { if (fs.readdirSync(p).length === 0) fs.rmdirSync(p); } catch {} };
for (const d of dirs) {
  const parts = d.split('/'); let cur = parts[0];
  for (const want of parts.slice(1)) {
    const entries = fs.readdirSync(cur);
    const others = entries.filter(e => e !== want && e.toLowerCase() === want.toLowerCase());
    for (const o of others) removeIfEmpty(path.join(cur, o));           // leftover empty folder
    const still = fs.readdirSync(cur).filter(e => e !== want && e.toLowerCase() === want.toLowerCase());
    if (still.length && !fs.readdirSync(cur).includes(want)) {          // same folder, wrong case
      const tmp = path.join(cur, want + '.tmp-rename');
      fs.renameSync(path.join(cur, still[0]), tmp);
      fs.renameSync(tmp, path.join(cur, want));
      console.log(`Fixed folder case on disk: ${path.join(cur, still[0])} -> ${want}`);
    }
    cur = path.join(cur, want);
  }
}

// ---- 4. Update references (path text only) and add srcDark, keeping each file's line endings
let refCount = 0, darkCount = 0;
const files = new Set([...Object.keys(DATA.edits), ...DATA.darks.map(x => x[0])]);
for (const f of files) {
  let text = fs.readFileSync(f, 'utf8');
  const eol = text.includes('\r\n') ? '\r\n' : '\n';
  for (const [o, nw] of DATA.edits[f] || []) {
    for (const [a, b] of [['"', '"'], ["'", "'"], ['(', ')']]) {
      const parts = text.split(a + o + b);
      refCount += parts.length - 1;
      text = parts.join(a + nw + b);
    }
  }
  const lines = text.split(/\r?\n/);
  for (const [, srcPath, darkPath] of DATA.darks.filter(x => x[0] === f)) {
    for (let i = 0; i < lines.length; i++) {
      const m = lines[i].match(/^(\s*)src=(["'])(.*?)\2/);
      if (!m || m[3] !== srcPath) continue;
      let has = false;
      for (let j = i + 1; j < lines.length; j++) {
        if (lines[j].includes('srcDark=')) { has = true; break; }
        if (lines[j].includes('/>')) break;
      }
      if (has) continue;
      lines.splice(i + 1, 0, `${m[1]}srcDark="${darkPath}"`);
      darkCount++; i++;
    }
  }
  fs.writeFileSync(f, lines.join(eol), 'utf8');
}
console.log(`Updated ${refCount} image paths and added ${darkCount} srcDark lines in ${files.size} files.`);

// ---- 5. Verify: every image path in the source points at a file git tracks (exact case)
const now = new Set(git('ls-files', '-z', '--', 'static').split('\0').filter(Boolean));
const textFiles = git('ls-files', '-z').split('\0').filter(p => p && !p.startsWith('static/') && p !== 'yarn.lock' && fs.existsSync(p));
const re = /"([^"\n]*img\/[^"\n]*)"|'([^'\n]*img\/[^'\n]*)'/g;
const broken = [];
for (const f of textFiles) {
  fs.readFileSync(f, 'utf8').split(/\r?\n/).forEach((line, i) => {
    for (const m of line.matchAll(re)) {
      const s = m[1] || m[2];
      if (!/\.(png|jpe?g|gif|svg|ico|webp)$/i.test(s)) continue;
      let p = s.startsWith('@site/') ? s.slice(6) : 'static/' + path.posix.normalize(s).replace(/^(\.\.\/)+/, '').replace(/^\/+/, '');
      p = p.replace(/%20/g, ' ');
      if (!now.has(p)) broken.push(`${f}:${i + 1}  ${s}`);
    }
  });
}
const known = ['Measure-Data-More-Screen-Light.jpg', 'docusaurus-social-card.jpg', 'undraw_docusaurus_'];
const unexpected = broken.filter(b => !known.some(k => b.includes(k)));
console.log('');
if (unexpected.length) { console.log('WARNING: image paths that do not match a file:'); unexpected.forEach(b => console.log('  ' + b)); }
else console.log('Verify: every image path matches a file (apart from the known ones listed in the notes).');
