echo
git status --short | awk '{print $1}' | sort | uniq -c | awk '{print "  "$2": "$1" files"}'
echo
echo 'Done. Nothing has been committed. Run "yarn clear" and then "yarn start", check a few pages in light and dark mode, then commit.'
